    '.ep-crop-btn.is-primary {',
    '  background: var(--color, #0F3A3A);',
    '  color: var(--base, #F5F5F5);',
    '  border-color: var(--color, #0F3A3A);',
    '}',
    '.ep-crop-btn.is-primary:hover { background: var(--point, #FF9A76); border-color: var(--point, #FF9A76); color: #fff; }',
    '.ep-empty-note {',
    '  text-align: center;',
