    // ─── 복구 모달 ───
    '.ep-modal-backdrop {',
    '  position: fixed;',
    '  top:0; left:0; right:0; bottom:0;',
    '  background: rgba(0,0,0,0.35);',
    '  z-index: 9999;',
    '  display: flex;',
    '  align-items: center;',
    '  justify-content: center;',
    '}',
    '.ep-modal {',
    '  background: var(--base, #F5F5F5);',
