    function close(){
      try { if (overlay.parentNode) overlay.parentNode.removeChild(overlay); } catch(_){}
    }

    var escHandler = function(e){
      if (e.key === 'Escape'){ close(); document.removeEventListener('keydown', escHandler); }
    };
